update fin_account
account_code = #{accountCode}, account_name = #{accountName}, account_type = #{accountType}, bank_name = #{bankName}, bank_no = #{bankNo}, is_default = #{isDefault}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where account_id = #{accountId}

mapper.select:
select j.journal_id, j.journal_no, j.account_id, coalesce(nullif(j.account_name, ''), a.account_name) as account_name, j.direction, j.biz_type, j.biz_id, j.biz_no, j.target_name, j.amount, j.before_balance, j.after_balance, j.occur_time, j.remark, j.create_by, j.create_time from fin_account_journal j left join fin_account a on a.account_id = j.account_id
and j.account_id = #{accountId}
and j.direction = #{direction}
and j.biz_type = #{bizType}
and j.biz_no like concat('%', #{bizNo}, '%')
and j.target_name like concat('%', #{targetName}, '%')
and j.occur_time >= concat(#{params.beginTime}, ' 00:00:00')
and j.occur_time < date_add(concat(#{params.endTime}, ' 00:00:00'), interval 1 day)
order by j.occur_time desc, j.journal_id desc

