update fin_period_close
close_status = #{closeStatus}, sale_amount_snapshot = #{saleAmountSnapshot}, purchase_amount_snapshot = #{purchaseAmountSnapshot}, closed_by = #{closedBy}, closed_time = #{closedTime}, reopen_reason = #{reopenReason}, remark = #{remark}, update_time = sysdate()
where period_id = #{periodId}
